import { Router, Request, Response } from 'express';

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export function isCreateBookmarkInput(value: unknown): value is CreateBookmarkInput {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  if (typeof candidate.url !== 'string') {
    return false;
  }
  if (candidate.title !== undefined && typeof candidate.title !== 'string') {
    return false;
  }
  if (
    candidate.tags !== undefined &&
    (!Array.isArray(candidate.tags) ||
      !candidate.tags.every((tag: unknown) => typeof tag === 'string'))
  ) {
    return false;
  }
  return true;
}

export const bookmarksRouter = Router();

bookmarksRouter.post('/', (req: Request, res: Response) => {
  const body: unknown = req.body;
  if (!isCreateBookmarkInput(body)) {
    res.status(400).json({ error: 'Invalid bookmark payload' });
    return;
  }

  res.status(201).json({
    url: body.url,
    title: body.title,
    tags: body.tags,
  });
});

import { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const bookmarksRouter = Router();

bookmarksRouter.post('/', (req: Request, res: Response, _next: NextFunction) => {
  const body: unknown = req.body;
  const result = createBookmarkSchema.safeParse(body);

  if (!result.success) {
    res.status(400).json({
      error: 'Validation failed',
      details: result.error.flatten(),
    });
    return;
  }

  const data: CreateBookmarkInput = result.data;
  res.status(201).json({
    url: data.url,
    title: data.title,
    tags: data.tags,
  });
});

import { randomUUID } from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL already exists: ${url}`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkNotFoundError extends Error {
  constructor(id: string) {
    super(`Bookmark not found: ${id}`);
    this.name = 'BookmarkNotFoundError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  public create(dto: CreateBookmarkDTO): Bookmark {
    for (const existing of this.bookmarks.values()) {
      if (existing.url === dto.url) {
        throw new DuplicateBookmarkError(dto.url);
      }
    }

    const bookmark: Bookmark = {
      id: randomUUID(),
      url: dto.url,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: dto.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(bookmark.id, bookmark);
    return bookmark;
  }

  public getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  public getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values());
  }

  public delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  public clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { bookmarkService, DuplicateBookmarkError } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const bookmarksRouter = Router();

bookmarksRouter.post('/', (req: Request, res: Response, next: NextFunction) => {
  const body: unknown = req.body;
  const result = createBookmarkSchema.safeParse(body);

  if (!result.success) {
    res.status(400).json({
      error: 'Validation failed',
      details: result.error.flatten(),
    });
    return;
  }

  try {
    const bookmark = bookmarkService.create(result.data);
    res.status(201).json(bookmark);
  } catch (error: unknown) {
    if (error instanceof DuplicateBookmarkError) {
      res.status(409).json({ error: error.message });
      return;
    }
    next(error);
  }
});

import { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { DuplicateBookmarkError, BookmarkNotFoundError } from '../services/bookmark-service.js';

interface HttpErrorLike {
  status?: number;
  statusCode?: number;
  type?: string;
  body?: unknown;
}

function isHttpErrorLike(error: unknown): error is HttpErrorLike {
  return typeof error === 'object' && error !== null;
}

export function errorHandler(
  err: unknown,
  _req: Request,
  res: Response,
  _next: NextFunction
): void {
  if (
    (err instanceof SyntaxError && isHttpErrorLike(err) && (err.status === 400 || err.statusCode === 400)) ||
    (isHttpErrorLike(err) && err.type === 'entity.parse.failed')
  ) {
    res.status(400).json({
      error: 'Invalid JSON payload',
    });
    return;
  }

  if (err instanceof ZodError) {
    res.status(422).json({
      error: 'Validation failed',
      details: err.errors,
    });
    return;
  }

  if (err instanceof DuplicateBookmarkError) {
    res.status(409).json({
      error: err.message,
    });
    return;
  }

  if (err instanceof BookmarkNotFoundError) {
    res.status(404).json({
      error: err.message,
    });
    return;
  }

  res.status(500).json({
    error: 'Internal server error',
  });
}

