import express from 'express';
import { bookmarksRouter } from './routes/bookmarks.js';
import { errorHandler } from './middleware/error-handler.js';

export const app = express();

app.use(express.json());

app.get('/health', (_req, res) => {
  res.json({ status: 'ok' });
});

app.use('/api/v1/bookmarks', bookmarksRouter);

app.use(errorHandler);

import { describe, it, expect } from 'vitest';
import { createBookmarkSchema } from './bookmarks.js';

describe('createBookmarkSchema', () => {
  it('should accept valid minimal input with only url', () => {
    const input = {
      url: 'https://example.com',
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe('https://example.com');
      expect(result.data.title).toBeUndefined();
      expect(result.data.tags).toBeUndefined();
    }
  });

  it('should accept valid full input with url, title, and tags', () => {
    const input = {
      url: 'https://example.com/docs',
      title: 'Valid Documentation Title',
      tags: ['typescript', 'express', 'zod'],
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe(input.url);
      expect(result.data.title).toBe(input.title);
      expect(result.data.tags).toEqual(input.tags);
    }
  });

  it('should accept maximum boundary valid input (title <= 200, 10 tags each <= 50 chars)', () => {
    const input = {
      url: 'https://example.com/boundary',
      title: 'a'.repeat(200),
      tags: Array.from({ length: 10 }, (_, i) => `tag-${i}-${'x'.repeat(40)}`),
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
  });

  it('should fail when url is missing', () => {
    const input = {
      title: 'Missing URL',
      tags: ['test'],
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const urlError = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlError).toBeDefined();
    }
  });

  it('should fail when url is not a valid url format', () => {
    const input = {
      url: 'not-a-valid-url',
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
  });

  it('should fail when url exceeds maximum length (url too long)', () => {
    const input = {
      url: `https://example.com/${'a'.repeat(2050)}`,
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const urlError = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlError).toBeDefined();
    }
  });

  it('should fail when title exceeds 200 characters', () => {
    const input = {
      url: 'https://example.com',
      title: 'a'.repeat(201),
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
  });

  it('should fail when there are too many tags (> 10)', () => {
    const input = {
      url: 'https://example.com',
      tags: Array.from({ length: 11 }, (_, i) => `tag${i}`),
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const tagsError = result.error.issues.find((issue) => issue.path.includes('tags'));
      expect(tagsError).toBeDefined();
    }
  });

  it('should fail when an individual tag is too long (> 50 chars)', () => {
    const input = {
      url: 'https://example.com',
      tags: ['valid-tag', 'a'.repeat(51)],
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const tagError = result.error.issues.find(
        (issue) => issue.path.includes('tags') && issue.path.includes(1)
      );
      expect(tagError).toBeDefined();
    }
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { BookmarkService, DuplicateBookmarkError } from './bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  describe('create', () => {
    it('should create a bookmark with generated id and createdAt timestamp', () => {
      const bookmark = service.create({
        url: 'https://example.com',
        title: 'Example',
        tags: ['web', 'test'],
      });

      expect(bookmark.id).toBeDefined();
      expect(typeof bookmark.id).toBe('string');
      expect(bookmark.id.length).toBeGreaterThan(0);
      expect(bookmark.url).toBe('https://example.com');
      expect(bookmark.title).toBe('Example');
      expect(bookmark.tags).toEqual(['web', 'test']);
      expect(bookmark.createdAt).toBeDefined();
      expect(new Date(bookmark.createdAt).toISOString()).toBe(bookmark.createdAt);
    });

    it('should create a bookmark without optional title or tags', () => {
      const bookmark = service.create({
        url: 'https://example.org',
      });

      expect(bookmark.id).toBeDefined();
      expect(bookmark.url).toBe('https://example.org');
      expect(bookmark.title).toBeUndefined();
      expect(bookmark.tags).toBeUndefined();
    });
  });

  describe('duplicate detection', () => {
    it('should throw DuplicateBookmarkError when creating with an existing URL', () => {
      service.create({
        url: 'https://duplicate.com',
        title: 'First',
      });

      expect(() => {
        service.create({
          url: 'https://duplicate.com',
          title: 'Second',
        });
      }).toThrow(DuplicateBookmarkError);
    });
  });

  describe('retrieval', () => {
    it('should retrieve a bookmark by id via getById', () => {
      const created = service.create({
        url: 'https://retrieval.com',
        title: 'Retrieval Test',
      });

      const retrieved = service.getById(created.id);
      expect(retrieved).toBeDefined();
      expect(retrieved?.id).toBe(created.id);
      expect(retrieved?.url).toBe('https://retrieval.com');
    });

    it('should return undefined when retrieving a nonexistent id', () => {
      const result = service.getById('non-existent-id');
      expect(result).toBeUndefined();
    });

    it('should retrieve all bookmarks via getAll', () => {
      service.create({ url: 'https://first.com' });
      service.create({ url: 'https://second.com' });

      const all = service.getAll();
      expect(all).toHaveLength(2);
      expect(all.map((b) => b.url)).toContain('https://first.com');
      expect(all.map((b) => b.url)).toContain('https://second.com');
    });

    it('should support deleting a bookmark', () => {
      const created = service.create({ url: 'https://delete-me.com' });
      const deleted = service.delete(created.id);
      expect(deleted).toBe(true);

      const found = service.getById(created.id);
      expect(found).toBeUndefined();
    });

    it('should clear all bookmarks via clear()', () => {
      service.create({ url: 'https://one.com' });
      service.create({ url: 'https://two.com' });
      service.clear();

      expect(service.getAll()).toHaveLength(0);
    });
  });
});

