export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export function parsePaginationParams(query: unknown): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  if (typeof query !== 'object' || query === null) {
    return { page, limit };
  }

  const record = query as Record<string, unknown>;

  if (typeof record.page === 'string') {
    const parsed = parseInt(record.page, 10);
    if (!isNaN(parsed)) {
      page = parsed < 1 ? 1 : parsed;
    }
  } else if (typeof record.page === 'number' && !isNaN(record.page)) {
    page = record.page < 1 ? 1 : Math.floor(record.page);
  }

  if (typeof record.limit === 'string') {
    const parsed = parseInt(record.limit, 10);
    if (!isNaN(parsed)) {
      if (parsed < 1) {
        limit = 1;
      } else if (parsed > 100) {
        limit = 100;
      } else {
        limit = parsed;
      }
    }
  } else if (typeof record.limit === 'number' && !isNaN(record.limit)) {
    const parsed = Math.floor(record.limit);
    if (parsed < 1) {
      limit = 1;
    } else if (parsed > 100) {
      limit = 100;
    } else {
      limit = parsed;
    }
  }

  return { page, limit };
}

export const bookmarksRouter = Router();

bookmarksRouter.get('/', (req: Request, res: Response) => {
  const query: unknown = req.query;
  const { page, limit } = parsePaginationParams(query);
  const result = bookmarkService.getPaginated(page, limit);
  res.status(200).json(result);
});

