import { describe, it, expect } from 'vitest';
import { createBookmarkSchema } from './bookmarks.js';

describe('createBookmarkSchema', () => {
  it('should accept valid minimal input with only url', () => {
    const input = {
      url: 'https://example.com',
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe('https://example.com');
      expect(result.data.title).toBeUndefined();
      expect(result.data.tags).toBeUndefined();
    }
  });

  it('should accept valid full input with url, title, and tags', () => {
    const input = {
      url: 'https://example.com/docs',
      title: 'Valid Documentation Title',
      tags: ['typescript', 'express', 'zod'],
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe(input.url);
      expect(result.data.title).toBe(input.title);
      expect(result.data.tags).toEqual(input.tags);
    }
  });

  it('should accept maximum boundary valid input (title <= 200, 10 tags each <= 50 chars)', () => {
    const input = {
      url: 'https://example.com/boundary',
      title: 'a'.repeat(200),
      tags: Array.from({ length: 10 }, (_, i) => `tag-${i}-${'x'.repeat(40)}`),
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
  });

  it('should fail when url is missing', () => {
    const input = {
      title: 'Missing URL',
      tags: ['test'],
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const urlError = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlError).toBeDefined();
    }
  });

  it('should fail when url is not a valid url format', () => {
    const input = {
      url: 'not-a-valid-url',
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
  });

  it('should fail when url exceeds maximum length (url too long)', () => {
    const input = {
      url: `https://example.com/${'a'.repeat(2050)}`,
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const urlError = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlError).toBeDefined();
    }
  });

  it('should fail when title exceeds 200 characters', () => {
    const input = {
      url: 'https://example.com',
      title: 'a'.repeat(201),
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
  });

  it('should fail when there are too many tags (> 10)', () => {
    const input = {
      url: 'https://example.com',
      tags: Array.from({ length: 11 }, (_, i) => `tag${i}`),
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const tagsError = result.error.issues.find((issue) => issue.path.includes('tags'));
      expect(tagsError).toBeDefined();
    }
  });

  it('should fail when an individual tag is too long (> 50 chars)', () => {
    const input = {
      url: 'https://example.com',
      tags: ['valid-tag', 'a'.repeat(51)],
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const tagError = result.error.issues.find(
        (issue) => issue.path.includes('tags') && issue.path.includes(1)
      );
      expect(tagError).toBeDefined();
    }
  });
});

