  it('should partially update title and tags', async () => {
    const created = await request(app)
      .post('/api/v1/bookmarks')
      .send({
        url: 'https://example.com/patch-test',
        title: 'Initial Title',
        tags: ['v1'],
      })
      .expect(201);

    const createdBody: unknown = created.body;
    expect(isBookmarkResponse(createdBody)).toBe(true);
    if (!isBookmarkResponse(createdBody)) {
      return;
    }

    // Update title only
    const patchTitleRes = await request(app)
      .patch(`/api/v1/bookmarks/${createdBody.id}`)
      .send({ title: 'Updated Title' })
      .expect(200);

    const patchTitleBody: unknown = patchTitleRes.body;
    expect(isBookmarkResponse(patchTitleBody)).toBe(true);
    if (isBookmarkResponse(patchTitleBody)) {
      expect(patchTitleBody.title).toBe('Updated Title');
      expect(patchTitleBody.tags).toEqual(['v1']);
      expect(patchTitleBody.url).toBe('https://example.com/patch-test');
    }

    // Update tags only
    const patchTagsRes = await request(app)
      .patch(`/api/v1/bookmarks/${createdBody.id}`)
      .send({ tags: ['v2', 'updated'] })
      .expect(200);

    const patchTagsBody: unknown = patchTagsRes.body;
    expect(isBookmarkResponse(patchTagsBody)).toBe(true);
    if (isBookmarkResponse(patchTagsBody)) {
      expect(patchTagsBody.title).toBe('Updated Title');
      expect(patchTagsBody.tags).toEqual(['v2', 'updated']);
      expect(patchTagsBody.url).toBe('https://example.com/patch-test');
    }
  });

  it('should return 404 when patching a missing ID', async () => {
    await request(app)
      .patch('/api/v1/bookmarks/nonexistent-id')
      .send({ title: 'New Title' })
      .expect(404);
  });

  it('should reject URL change attempt with 400 Bad Request', async () => {
    const created = await request(app)
      .post('/api/v1/bookmarks')
      .send({
        url: 'https://example.com/immutable-url',
        title: 'Original',
      })
      .expect(201);

    const createdBody: unknown = created.body;
    expect(isBookmarkResponse(createdBody)).toBe(true);
    if (!isBookmarkResponse(createdBody)) {
      return;
    }

    await request(app)
      .patch(`/api/v1/bookmarks/${createdBody.id}`)
      .send({ url: 'https://example.com/attempted-new-url' })
      .expect(400);

    // Verify the URL was not changed
    const getRes = await request(app)
      .get(`/api/v1/bookmarks/${createdBody.id}`)
      .expect(200);

    const getBody: unknown = getRes.body;
    expect(isBookmarkResponse(getBody)).toBe(true);
    if (isBookmarkResponse(getBody)) {
      expect(getBody.url).toBe('https://example.com/immutable-url');
    }
  });
});

