import { describe, it, expect, vi } from 'vitest';
import request from 'supertest';
import { app } from '../app.js';

interface ParsedLog {
  method: string;
  path: string;
  status: number;
  duration_ms: number;
}

function isParsedLog(data: unknown): data is ParsedLog {
  if (typeof data !== 'object' || data === null) {
    return false;
  }
  const item = data as Record<string, unknown>;
  return (
    typeof item.method === 'string' &&
    typeof item.path === 'string' &&
    typeof item.status === 'number' &&
    typeof item.duration_ms === 'number'
  );
}

describe('requestLogger middleware', () => {
  it('should log method, path, status, and duration_ms in JSON format', async () => {
    const logSpy = vi.spyOn(console, 'log').mockImplementation(() => {});

    await request(app).get('/health').expect(200);

    expect(logSpy).toHaveBeenCalled();
    const lastCall = logSpy.mock.calls[logSpy.mock.calls.length - 1];
    expect(lastCall).toBeDefined();
    if (lastCall && typeof lastCall[0] === 'string') {
      const parsed: unknown = JSON.parse(lastCall[0]);
      expect(isParsedLog(parsed)).toBe(true);
      if (isParsedLog(parsed)) {
        expect(parsed.method).toBe('GET');
        expect(parsed.path).toBe('/health');
        expect(parsed.status).toBe(200);
        expect(parsed.duration_ms).toBeGreaterThanOrEqual(0);
      }
    }

    logSpy.mockRestore();
  });
});

