  if (!existing) {
    return undefined;
  }

  const updated: Bookmark = {
    ...existing,
    ...(dto.title !== undefined ? { title: dto.title } : {}),
    ...(dto.tags !== undefined ? { tags: dto.tags } : {}),
  };

  this.bookmarks.set(id, updated);
  return updated;
}

public search(term: string): Bookmark[] {
  const normalized = term.trim().toLowerCase();
  if (!normalized) {
    return [];
  }

  return this.getAll().filter((bookmark) => {
    const titleMatches =
      bookmark.title !== undefined &&
      bookmark.title.toLowerCase().includes(normalized);

    const tagMatches =
      bookmark.tags !== undefined &&
      bookmark.tags.some((tag) => tag.toLowerCase() === normalized);

    return titleMatches || tagMatches;
  });
}

