import { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { bookmarkService } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const updateBookmarkSchema = z.object({
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type UpdateBookmarkInput = z.infer<typeof updateBookmarkSchema>;

export function parsePaginationParams(query: unknown): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  if (typeof query !== 'object' || query === null) {
    return { page, limit };
  }

  const record = query as Record<string, unknown>;

  if (typeof record.page === 'string') {
    const parsed = parseInt(record.page, 10);
    if (!isNaN(parsed)) {
      page = parsed < 1 ? 1 : parsed;
    }
  } else if (typeof record.page === 'number' && !isNaN(record.page)) {
    page = record.page < 1 ? 1 : Math.floor(record.page);
  }

  if (typeof record.limit === 'string') {
    const parsed = parseInt(record.limit, 10);
    if (!isNaN(parsed)) {
      if (parsed < 1) {
        limit = 1;
      } else if (parsed > 100) {
        limit = 100;
      } else {
        limit = parsed;
      }
    }
  } else if (typeof record.limit === 'number' && !isNaN(record.limit)) {
    const parsed = Math.floor(record.limit);
    if (parsed < 1) {
      limit = 1;
    } else if (parsed > 100) {
      limit = 100;
    } else {
      limit = parsed;
    }
  }

  return { page, limit };
}

export const bookmarksRouter = Router();

bookmarksRouter.get('/', (req: Request, res: Response) => {
  const query: unknown = req.query;
  const { page, limit } = parsePaginationParams(query);
  const result = bookmarkService.getPaginated(page, limit);
  res.status(200).json(result);
});

bookmarksRouter.get('/:id', (req: Request, res: Response) => {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }
  const bookmark = bookmarkService.getById(id);
  if (!bookmark) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(200).json(bookmark);
});

bookmarksRouter.delete('/:id', (req: Request, res: Response) => {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }
  const deleted = bookmarkService.delete(id);
  if (!deleted) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(204).send();
});

bookmarksRouter.patch('/:id', (req: Request, res: Response, next: NextFunction) => {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }

  const body: unknown = req.body;
  if (typeof body === 'object' && body !== null && 'url' in body) {
    res.status(400).json({ error: 'URL is immutable and cannot be updated' });
    return;
  }

  try {
    const data = updateBookmarkSchema.parse(body);
    const updated = bookmarkService.update(id, data);
    if (!updated) {
      res.status(404).json({ error: `Bookmark not found: ${id}` });
      return;
    }
    res.status(200).json(updated);
  } catch (error: unknown) {
    next(error);
  }
});

bookmarksRouter.post('/', (req: Request, res: Response, next: NextFunction) => {
  try {
    const body: unknown = req.body;
    const data = createBookmarkSchema.parse(body);
    const bookmark = bookmarkService.create(data);
    res.status(201).json(bookmark);
  } catch (error: unknown) {
    next(error);
  }
});

