import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService } from '../src/services/bookmark-service.js';

interface BookmarkResponse {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

interface PaginatedBookmarkResponse {
  data: BookmarkResponse[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

function isBookmarkResponse(data: unknown): data is BookmarkResponse {
  if (typeof data !== 'object' || data === null) {
    return false;
  }
  const item = data as Record<string, unknown>;
  return (
    typeof item.id === 'string' &&
    typeof item.url === 'string' &&
    typeof item.createdAt === 'string'
  );
}

function isPaginatedBookmarkResponse(data: unknown): data is PaginatedBookmarkResponse {
  if (typeof data !== 'object' || data === null) {
    return false;
  }
  const item = data as Record<string, unknown>;
  if (!Array.isArray(item.data)) {
    return false;
  }
  if (typeof item.pagination !== 'object' || item.pagination === null) {
    return false;
  }
  const pag = item.pagination as Record<string, unknown>;
  return (
    typeof pag.page === 'number' &&
    typeof pag.limit === 'number' &&
    typeof pag.total === 'number' &&
    typeof pag.totalPages === 'number'
  );
}

describe('Bookmarks API Integration Tests', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  describe('POST /api/v1/bookmarks', () => {
    it('should create a new bookmark and return 201 Created', async () => {
      const payload = {
        url: 'https://example.com/integration',
        title: 'Integration Test Bookmark',
        tags: ['integration', 'test'],
      };

      const response = await request(app)
        .post('/api/v1/bookmarks')
        .send(payload)
        .expect(201);

      const body: unknown = response.body;
      expect(isBookmarkResponse(body)).toBe(true);
      if (isBookmarkResponse(body)) {
        expect(body.id).toBeDefined();
        expect(body.url).toBe(payload.url);
        expect(body.title).toBe(payload.title);
        expect(body.tags).toEqual(payload.tags);
        expect(body.createdAt).toBeDefined();
      }
    });
  });

  describe('GET /api/v1/bookmarks', () => {
    it('should return a paginated list of bookmarks with 200 OK', async () => {
      await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/first' })
        .expect(201);

      await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/second' })
        .expect(201);

      const response = await request(app)
        .get('/api/v1/bookmarks?page=1&limit=20')
        .expect(200);

      const body: unknown = response.body;
      expect(isPaginatedBookmarkResponse(body)).toBe(true);
      if (isPaginatedBookmarkResponse(body)) {
        expect(body.data).toHaveLength(2);
        expect(body.pagination.page).toBe(1);
        expect(body.pagination.limit).toBe(20);
        expect(body.pagination.total).toBe(2);
        expect(body.pagination.totalPages).toBe(1);
      }
    });

    it('should handle edge case: page 0 normalizes to page 1', async () => {
      await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/edge-page-0' })
        .expect(201);

      const response = await request(app)
        .get('/api/v1/bookmarks?page=0')
        .expect(200);

      const body: unknown = response.body;
      expect(isPaginatedBookmarkResponse(body)).toBe(true);
      if (isPaginatedBookmarkResponse(body)) {
        expect(body.pagination.page).toBe(1);
      }
    });

    it('should handle edge case: negative limit clamps to 1', async () => {
      await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/edge-neg-limit' })
        .expect(201);

      const response = await request(app)
        .get('/api/v1/bookmarks?limit=-10')
        .expect(200);

      const body: unknown = response.body;
      expect(isPaginatedBookmarkResponse(body)).toBe(true);
      if (isPaginatedBookmarkResponse(body)) {
        expect(body.pagination.limit).toBe(1);
      }
    });

    it('should handle edge case: limit > 100 caps at 100', async () => {
      await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/edge-over-100' })
        .expect(201);

      const response = await request(app)
        .get('/api/v1/bookmarks?limit=250')
        .expect(200);

      const body: unknown = response.body;
      expect(isPaginatedBookmarkResponse(body)).toBe(true);
      if (isPaginatedBookmarkResponse(body)) {
        expect(body.pagination.limit).toBe(100);
      }
    });
  });

  describe('GET /api/v1/bookmarks/:id', () => {
    it('should return a single bookmark by ID with 200 OK', async () => {
      const created = await request(app)
        .post('/api/v1/bookmarks')
        .send({
          url: 'https://example.com/single',
          title: 'Single Bookmark',
        })
        .expect(201);

      const createdBody: unknown = created.body;
      expect(isBookmarkResponse(createdBody)).toBe(true);
      if (!isBookmarkResponse(createdBody)) {
        return;
      }

      const response = await request(app)
        .get(`/api/v1/bookmarks/${createdBody.id}`)
        .expect(200);

      const body: unknown = response.body;
      expect(isBookmarkResponse(body)).toBe(true);
      if (isBookmarkResponse(body)) {
        expect(body.id).toBe(createdBody.id);
        expect(body.url).toBe('https://example.com/single');
        expect(body.title).toBe('Single Bookmark');
      }
    });
  });

  describe('DELETE /api/v1/bookmarks/:id', () => {
    it('should delete an existing bookmark with 204 No Content', async () => {
      const created = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/delete-target' })
        .expect(201);

      const createdBody: unknown = created.body;
      expect(isBookmarkResponse(createdBody)).toBe(true);
      if (!isBookmarkResponse(createdBody)) {
        return;
      }

      await request(app)
        .delete(`/api/v1/bookmarks/${createdBody.id}`)
        .expect(204);

      await request(app)
        .get(`/api/v1/bookmarks/${createdBody.id}`)
        .expect(404);
    });
  });

  describe('PATCH /api/v1/bookmarks/:id', () => {
    it('should partially update title and tags', async () => {
      const created = await request(app)
        .post('/api/v1/bookmarks')
        .send({
          url: 'https://example.com/patch-test',
          title: 'Initial Title',
          tags: ['v1'],
        })
        .expect(201);

      const createdBody: unknown = created.body;
      expect(isBookmarkResponse(createdBody)).toBe(true);
      if (!isBookmarkResponse(createdBody)) {
        return;
      }

      // Update title only
      const patchTitleRes = await request(app)
        .patch(`/api/v1/bookmarks/${createdBody.id}`)
        .send({ title: 'Updated Title' })
        .expect(200);

      const patchTitleBody: unknown = patchTitleRes.body;
      expect(isBookmarkResponse(patchTitleBody)).toBe(true);
      if (isBookmarkResponse(patchTitleBody)) {
        expect(patchTitleBody.title).toBe('Updated Title');
        expect(patchTitleBody.tags).toEqual(['v1']);
        expect(patchTitleBody.url).toBe('https://example.com/patch-test');
      }

      // Update tags only
      const patchTagsRes = await request(app)
        .patch(`/api/v1/bookmarks/${createdBody.id}`)
        .send({ tags: ['v2', 'updated'] })
        .expect(200);

      const patchTagsBody: unknown = patchTagsRes.body;
      expect(isBookmarkResponse(patchTagsBody)).toBe(true);
      if (isBookmarkResponse(patchTagsBody)) {
        expect(patchTagsBody.title).toBe('Updated Title');
        expect(patchTagsBody.tags).toEqual(['v2', 'updated']);
        expect(patchTagsBody.url).toBe('https://example.com/patch-test');
      }
    });

    it('should return 404 when patching a missing ID', async () => {
      await request(app)
        .patch('/api/v1/bookmarks/nonexistent-id')
        .send({ title: 'New Title' })
        .expect(404);
    });

    it('should reject URL change attempt with 400 Bad Request', async () => {
      const created = await request(app)
        .post('/api/v1/bookmarks')
        .send({
          url: 'https://example.com/immutable-url',
          title: 'Original',
        })
        .expect(201);

      const createdBody: unknown = created.body;
      expect(isBookmarkResponse(createdBody)).toBe(true);
      if (!isBookmarkResponse(createdBody)) {
        return;
      }

      await request(app)
        .patch(`/api/v1/bookmarks/${createdBody.id}`)
        .send({ url: 'https://example.com/attempted-new-url' })
        .expect(400);

      // Verify the URL was not changed
      const getRes = await request(app)
        .get(`/api/v1/bookmarks/${createdBody.id}`)
        .expect(200);

      const getBody: unknown = getRes.body;
      expect(isBookmarkResponse(getBody)).toBe(true);
      if (isBookmarkResponse(getBody)) {
        expect(getBody.url).toBe('https://example.com/immutable-url');
      }
    });
  });
});

