import { randomUUID } from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export interface UpdateBookmarkDTO {
  title?: string;
  tags?: string[];
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL already exists: ${url}`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkNotFoundError extends Error {
  constructor(id: string) {
    super(`Bookmark not found: ${id}`);
    this.name = 'BookmarkNotFoundError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  /**
   * Creates a new bookmark with a generated UUID and ISO timestamp.
   *
   * @param dto - Data transfer object containing URL, optional title, and optional tags.
   * @returns The created bookmark entity.
   * @throws {DuplicateBookmarkError} When a bookmark with the same URL already exists.
   *
   * @example
   * ```ts
   * const bookmark = service.create({
   *   url: 'https://example.com',
   *   title: 'Example',
   *   tags: ['sample']
   * });
   * ```
   */
  public create(dto: CreateBookmarkDTO): Bookmark {
    for (const existing of this.bookmarks.values()) {
      if (existing.url === dto.url) {
        throw new DuplicateBookmarkError(dto.url);
      }
    }

    const bookmark: Bookmark = {
      id: randomUUID(),
      url: dto.url,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: dto.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(bookmark.id, bookmark);
    return bookmark;
  }

  /**
   * Retrieves a bookmark by its unique identifier.
   *
   * @param id - Unique UUID of the bookmark.
   * @returns The matching bookmark, or undefined if not found.
   *
   * @example
   * ```ts
   * const bookmark = service.getById('123e4567-e89b-12d3-a456-426614174000');
   * if (bookmark) {
   *   console.log(bookmark.title);
   * }
   * ```
   */
  public getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  /**
   * Retrieves all bookmarks sorted by creation time in descending order.
   *
   * @returns An array of all bookmarks, newest first.
   *
   * @example
   * ```ts
   * const allBookmarks = service.getAll();
   * console.log(`Total bookmarks: ${allBookmarks.length}`);
   * ```
   */
  public getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  /**
   * Retrieves a paginated subset of all bookmarks sorted by creation time descending.
   *
   * @param page - 1-indexed page number.
   * @param limit - Maximum number of items per page.
   * @returns Paginated result containing bookmark array and pagination metadata.
   *
   * @example
   * ```ts
   * const page1 = service.getPaginated(1, 20);
   * console.log(`Page ${page1.pagination.page} of ${page1.pagination.totalPages}`);
   * ```
   */
  public getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const data = all.slice(startIndex, startIndex + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  /**
   * Deletes a bookmark by its unique identifier.
   *
   * @param id - Unique UUID of the bookmark to delete.
   * @returns True if the bookmark was found and deleted, false otherwise.
   *
   * @example
   * ```ts
   * const wasDeleted = service.delete('123e4567-e89b-12d3-a456-426614174000');
   * if (!wasDeleted) {
   *   console.log('Bookmark not found');
   * }
   * ```
   */
  public delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  /**
   * Partially updates an existing bookmark's title and tags.
   * URLs and IDs are immutable and cannot be updated.
   *
   * @param id - Unique UUID of the bookmark to update.
   * @param dto - Partial fields to update (title and/or tags).
   * @returns The updated bookmark entity, or undefined if not found.
   *
   * @example
   * ```ts
   * const updated = service.update('123e4567-e89b-12d3-a456-426614174000', {
   *   title: 'New Title'
   * });
   * ```
   */
  public update(id: string, dto: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: dto.tags } : {}),
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  /**
   * Searches bookmarks matching a search term across title (case-insensitive substring)
   * or tags (exact match, case-insensitive).
   *
   * @param term - The search query term.
   * @returns Array of bookmarks matching the search criteria, newest first.
   *
   * @example
   * ```ts
   * const results = service.search('typescript');
   * for (const item of results) {
   *   console.log(item.title);
   * }
   * ```
   */
  public search(term: string): Bookmark[] {
    const normalized = term.trim().toLowerCase();
    if (!normalized) {
      return [];
    }

    return this.getAll().filter((bookmark) => {
      const titleMatches =
        bookmark.title !== undefined &&
        bookmark.title.toLowerCase().includes(normalized);

      const tagMatches =
        bookmark.tags !== undefined &&
        bookmark.tags.some((tag) => tag.toLowerCase() === normalized);

      return titleMatches || tagMatches;
    });
  }

  /**
   * Clears all bookmarks from memory. Primarily used for resetting test state.
   *
   * @returns void
   *
   * @example
   * ```ts
   * service.clear();
   * console.log(service.getAll().length); // 0
   * ```
   */
  public clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

