import { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { bookmarkService } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const updateBookmarkSchema = z.object({
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type UpdateBookmarkInput = z.infer<typeof updateBookmarkSchema>;

/**
 * Parses and sanitizes pagination query parameters from an unknown input.
 *
 * @param query - Raw query object from Express request.
 * @returns An object containing normalized page and limit numbers.
 *
 * @example
 * ```ts
 * const { page, limit } = parsePaginationParams({ page: '2', limit: '50' });
 * ```
 */
export function parsePaginationParams(query: unknown): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  if (typeof query !== 'object' || query === null) {
    return { page, limit };
  }

  const record = query as Record<string, unknown>;

  if (typeof record.page === 'string') {
    const parsed = parseInt(record.page, 10);
    if (!isNaN(parsed)) {
      page = parsed < 1 ? 1 : parsed;
    }
  } else if (typeof record.page === 'number' && !isNaN(record.page)) {
    page = record.page < 1 ? 1 : Math.floor(record.page);
  }

  if (typeof record.limit === 'string') {
    const parsed = parseInt(record.limit, 10);
    if (!isNaN(parsed)) {
      if (parsed < 1) {
        limit = 1;
      } else if (parsed > 100) {
        limit = 100;
      } else {
        limit = parsed;
      }
    }
  } else if (typeof record.limit === 'number' && !isNaN(record.limit)) {
    const parsed = Math.floor(record.limit);
    if (parsed < 1) {
      limit = 1;
    } else if (parsed > 100) {
      limit = 100;
    } else {
      limit = parsed;
    }
  }

  return { page, limit };
}

/**
 * Route handler for GET /api/v1/bookmarks.
 * Retrieves a paginated list of bookmarks sorted by createdAt descending.
 *
 * @param req - Express request object with optional page and limit query parameters.
 * @param res - Express response object.
 * @returns void
 *
 * @example
 * ```http
 * GET /api/v1/bookmarks?page=1&limit=20 HTTP/1.1
 * ```
 */
export function listBookmarksHandler(req: Request, res: Response): void {
  const query: unknown = req.query;
  const { page, limit } = parsePaginationParams(query);
  const result = bookmarkService.getPaginated(page, limit);
  res.status(200).json(result);
}

/**
 * Route handler for GET /api/v1/bookmarks/search.
 * Searches bookmarks by title (case-insensitive substring) or tags (exact match).
 *
 * @param req - Express request object containing the 'q' query parameter.
 * @param res - Express response object.
 * @returns void
 *
 * @example
 * ```http
 * GET /api/v1/bookmarks/search?q=typescript HTTP/1.1
 * ```
 */
export function searchBookmarksHandler(req: Request, res: Response): void {
  const q: unknown = req.query.q;
  if (typeof q !== 'string' || q.trim() === '') {
    res.status(400).json({ error: 'Search query parameter "q" is required and cannot be empty' });
    return;
  }

  const results = bookmarkService.search(q);
  res.status(200).json(results);
}

/**
 * Route handler for GET /api/v1/bookmarks/:id.
 * Retrieves a single bookmark by its unique ID.
 *
 * @param req - Express request object containing the bookmark 'id' parameter.
 * @param res - Express response object.
 * @returns void
 *
 * @example
 * ```http
 * GET /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000 HTTP/1.1
 * ```
 */
export function getBookmarkByIdHandler(req: Request, res: Response): void {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }
  const bookmark = bookmarkService.getById(id);
  if (!bookmark) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(200).json(bookmark);
}

/**
 * Route handler for DELETE /api/v1/bookmarks/:id.
 * Deletes a bookmark by its unique ID.
 *
 * @param req - Express request object containing the bookmark 'id' parameter.
 * @param res - Express response object.
 * @returns void
 *
 * @example
 * ```http
 * DELETE /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000 HTTP/1.1
 * ```
 */
export function deleteBookmarkHandler(req: Request, res: Response): void {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }
  const deleted = bookmarkService.delete(id);
  if (!deleted) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(204).send();
}

/**
 * Route handler for PATCH /api/v1/bookmarks/:id.
 * Partially updates an existing bookmark's title and/or tags. URL is immutable.
 *
 * @param req - Express request object containing 'id' parameter and update body.
 * @param res - Express response object.
 * @param next - Express next middleware function for error delegation.
 * @returns void
 *
 * @example
 * ```http
 * PATCH /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000 HTTP/1.1
 * Content-Type: application/json
 *
 * { "title": "Updated Title" }
 * ```
 */
export function updateBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }

  const body: unknown = req.body;
  if (typeof body === 'object' && body !== null && 'url' in body) {
    res.status(400).json({ error: 'URL is immutable and cannot be updated' });
    return;
  }

  try {
    const data = updateBookmarkSchema.parse(body);
    const updated = bookmarkService.update(id, data);
    if (!updated) {
      res.status(404).json({ error: `Bookmark not found: ${id}` });
      return;
    }
    res.status(200).json(updated);
  } catch (error: unknown) {
    next(error);
  }
}

/**
 * Route handler for POST /api/v1/bookmarks.
 * Creates a new bookmark with a URL, optional title, and optional tags.
 *
 * @param req - Express request object containing the creation payload.
 * @param res - Express response object.
 * @param next - Express next middleware function for error delegation.
 * @returns void
 *
 * @example
 * ```http
 * POST /api/v1/bookmarks HTTP/1.1
 * Content-Type: application/json
 *
 * {
 *   "url": "https://example.com",
 *   "title": "Example",
 *   "tags": ["web"]
 * }
 * ```
 */
export function createBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
  try {
    const body: unknown = req.body;
    const data = createBookmarkSchema.parse(body);
    const bookmark = bookmarkService.create(data);
    res.status(201).json(bookmark);
  } catch (error: unknown) {
    next(error);
  }
}

export const bookmarksRouter = Router();

bookmarksRouter.get('/', listBookmarksHandler);
bookmarksRouter.get('/search', searchBookmarksHandler);
bookmarksRouter.get('/:id', getBookmarkByIdHandler);
bookmarksRouter.delete('/:id', deleteBookmarkHandler);
bookmarksRouter.patch('/:id', updateBookmarkHandler);
bookmarksRouter.post('/', createBookmarkHandler);
